draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';

  // Draw a simple numeral '1571'
  ctx.font = '48px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.strokeText('1571', W/2, H/2 + Math.sin(t) * 20);
  ctx.fillText('1571', W/2, H/2 + Math.sin(t) * 20);

  ctx.restore();
}
